<div class="page-actions"><form class="filter-bar"><div class="input-icon"><i class="bi bi-search"></i><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Aksi, entitas, user..."></div><button class="btn btn-light">Cari</button></form><span class="text-muted">Maksimal 500 log terbaru</span></div>
<div class="panel-card"><div class="table-responsive"><table class="table modern-table align-middle"><thead><tr><th>Waktu</th><th>User</th><th>Aksi</th><th>Entitas</th><th>ID</th><th>IP</th><th>Perubahan</th></tr></thead><tbody><?php foreach($logs as$l):?><tr><td><?= format_datetime($l['created_at']) ?></td><td><?= e($l['user_name']??'System') ?></td><td><span class="code-pill"><?= e(strtoupper($l['action'])) ?></span></td><td><?= e($l['entity_type']) ?></td><td><?= e($l['entity_id']??'-') ?></td><td><?= e($l['ip_address']??'-') ?></td><td><details><summary>Lihat JSON</summary><pre><?= e($l['after_data']??$l['before_data']??'-') ?></pre></details></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="7" class="empty-state">Audit log kosong.</td></tr><?php endif;?></tbody></table></div></div>
